#!/usr/bin/env bash
# ============================================================
# Codex_ok — 一键部署脚本（自解压包）
# ============================================================
# 用法: bash build-codex-ok.sh [目标目录]
# 缺省目标: ./Codex_ok
#
# 包含 54 个文件，完整还原 Codex_ok 项目结构:
#   .opencode/
#     commands/      (9 个 Comet slash command)
#     rules/         (1 个 comet-phase-guard)
#     skills/        (Comet 五阶段 skills + runtime + scripts + reference)
#     .gitignore
#     package.json
# ============================================================

set -euo pipefail

TARGET="${1:-${PWD}/Codex_ok}"

echo "============================================"
echo "  Codex_ok — 一键部署"
echo "============================================"
echo "  目标: ${TARGET}"
echo "  文件: 54 个"
echo

mkdir -p "$TARGET"

# base64 编码数据（自此行之后）
PAYLOAD_BASE64=""

echo "  正在解压..."
echo "$PAYLOAD_BASE64" | base64 -d | tar xzf - -C "$TARGET"

count=$(find "$TARGET" -type f | wc -l)
echo
echo "  完成: ${count} 个文件已还原到 ${TARGET}"
echo
echo "  目录结构:"
find "$TARGET" -type f | sort | while read f; do
  echo "    ${f#$TARGET/}"
done | head -60
echo
echo "============================================"
echo "  部署完毕"
echo "============================================"
